            "arabicText": "«كَانَ يُوسُفُ عَلَيْهِ السَّلَامُ أَحْسَنَ إِخْوَتِهِ خُلُقاً وَصُورَةً، فَحَسَدَهُ إِخْوَتُهُ وَأَلْقَوْهُ فِي غَيَابَتِ الجُبِّ، وَقَالُوا لِأَبِيهِمْ: أَكَلَهُ الذِّئْبُ! فَقَالَ يَعْقُوبُ: {فَصَبْرٌ جَمِيلٌ وَاللَّهُ الْمُسْتَعَانُ}. وَبِيعَ يُوسُفُ فِي مِصْرَ بِثَمَنٍ بَخْسٍ، ثُمَّ ابْتُلِيَ بِفِتْنَةِ امْرَأَةِ العَزِيزِ فَآثَرَ السِّجْنَ عَلَى المَعْصِيَةِ، فَمَكُثَ فِي السِّجْنِ بِضْعَ سِنِينَ دَاعِياً إِلَى التَّوْحِيدِ، حَتَّى أَظْهَرَ اللَّهُ بَرَاءَتَهُ وَمَكَّنَ لَهُ فِي الأَرْضِ، فَلَمَّا جَاءَهُ إِخْوَتُهُ قَالَ لَهُمْ بِعَفْوِ الأَنْبِيَاءِ: {لَا تَثْرِيبَ عَلَيْكُمُ الْيَوْمَ يَغْفِرُ اللَّهُ لَكُمْ وَهُوَ أَرْحَمُ الرَّاحِمِينَ}».",
            "urduTranslation": "علامہ ندوی فرماتے ہیں: 'حضرت یوسف علیہ السلام اپنے تمام بھائیوں میں سب سے زیادہ خوبصورت اور با اخلاق تھے، ان کے بھائیوں نے حسد کیا اور انہیں ایک اندھے کنویں میں پھینک دیا، اور اپنے والد سے جا کر جھوٹ بول دیا کہ یوسف کو بھیڑیا کھا گیا ہے! تو حضرت یعقوب علیہ السلام نے فرمایا: {پس صبرِ جمیل ہی بہتر ہے اور اللہ ہی سے مدد مانگی جاتی ہے}۔ اور یوسف علیہ السلام کو مصر کے بازار میں چند کھوٹے سکوں کے بدلے بیچ دیا گیا، پھر عزیزِ مصر کی بیوی کی فتنے انگیز آزمائش آئی تو آپ نے گناہ پر قید خانے کی مشقت کو ترجیح دی، اور کئی سال جیل کی تنہائی میں توحید کی دعوت دیتے رہے، یہاں تک کہ اللہ نے آپ کی پاک دامنی کو روزِ روشن کی طرح عیاں کر دیا اور آپ کو مصر کی حکومت اور اقتدار بخشا؛ اور جب وہی حسد کرنے والے بھائی آپ کے دربار میں جھولی پھیلائے آئے تو آپ نے انبیاء کی شانِ عفو کا مظاہرہ کرتے ہوئے فرمایا: {آج کے دن تم پر کوئی ملامت نہیں، اللہ تمہیں معاف فرمائے اور وہ سب سے بڑھ کر رحم کرنے والا ہے}'۔",
