            "urduTranslation": "حافظ سیوطی فرماتے ہیں: 'سیدنا عمر بن خطاب رضی اللہ عنہ پہلے حکمران تھے جنہیں 'امیر المؤمنین' کا لقب دیا گیا، پہلے شخص تھے جنہوں نے ہجری تقویم کی بنیاد رکھی، پہلے شخص تھے جنہوں نے سرکاری محکمے (دیوان) قائم کیے، اور پہلے حکمران تھے جو راتوں کو گلیوں میں گشت کر کے اپنی رعایا کے دکھ درد کی خبر لیتے تھے۔ ان کے مبارک دور میں قیصر و کسریٰ کی عظیم سلطنتیں فتح ہوئیں، بصرہ، کوفہ اور فسطاط جیسے نئے شہر آباد ہوئے، لیکن اس تمام کروفر کے باوجود آپ کی ذاتی خوراک روٹی اور زیتون کا تیل تھا، اور لباس میں بارہ پیوند لگے ہوتے تھے، اور فرماتے تھے: 'اگر فرات کے کنارے ایک بکری کا بچہ بھی بے یارومددگار مر جائے تو مجھے ڈر ہے کہ قیامت کے دن اللہ عمر سے اس کی بازپرس فرمائے گا'۔",
