            "arabicText": "«اعْلَمْ أَنَّ التَّاجِرَ فِي الدُّنْيَا لَا يَتِمُّ لَهُ رِبْحٌ إِلَّا بِمُحَاسَبَةِ شَرِيكِهِ، وَكَذَلِكَ العَبْدُ الكَيِّسُ يَجِبُ أَنْ يُحَاسِبَ نَفْسَهُ فِي سَفَرِ الآخِرَةِ عَلَى سِتِّ مَقَامَاتٍ: المَقَامُ الأَوَّلُ: المُشَارَطَةُ، وَهِيَ أَنْ يَشْتَرِطَ عَلَى نَفْسِهِ عِنْدَ الصَّبَاحِ حِفْظَ الجَوَارِحِ وَالطَّاعَاتِ. المَقَامُ الثَّانِي: المُرَاقَبَةُ، وَهِيَ اسْتِحْضَارُ نَظَرِ اللَّهِ إِلَيْهِ فِي كُلِّ حَرَكَةٍ. المَقَامُ الثَّالِثُ: المُحَاسَبَةُ بَعْدَ العَمَلِ عِنْدَ النَّوْمِ. المَقَامُ الرَّابِعُ: المُعَاقَبَةُ لِلنَّفْسِ عَلَى تَقْصِيرِهَا بِالصِّيَامِ وَالصَّدَقَةِ. المَقَامُ الخَامِسُ: المُجَاهَدَةُ بِإِلْزَامِهَا مَا يَثْقُلُ عَلَيْهَا. المَقَامُ السَّادِسُ: المُعَاتَبَةُ وَتَوْبِيخُ النَّفْسِ عَلَى غَفْلَتِهَا».",
