            "id": "tanbih_samarqandi_seg_1_2",
            "arabicText": "«قَالَ أَبُو اللَّيْثِ: قَرَنَ اللَّهُ تَعَالَى شُكْرَ الوَالِدَيْنِ بِشُكْرِهِ فَقَالَ: {أَنِ اشْكُرْ لِي وَلِوَالِدَيْكَ إِلَيَّ الْمَصِيرُ}؛ فَمَنْ شَكَرَ اللَّهَ وَلَمْ يَشْكُرْ وَالِدَيْهِ لَمْ يُقْبَلْ مِنْهُ. وَعَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: جَاءَ رَجُلٌ إِلَى رَسُولِ اللَّهِ ﷺ فَقَالَ: مَنْ أَحَقُّ النَّاسِ بِحُسْنِ صَحَابَتِي؟ قَالَ: «أُمُّكَ»، قَالَ: ثُمَّ مَنْ؟ قَالَ: «أُمُّكَ»، قَالَ: ثُمَّ مَنْ؟ قَالَ: «أُمُّكَ»، قَالَ: ثُمَّ مَنْ؟ قَالَ: «ثُمَّ أَبُوكَ». وَعُقُوقُ الوَالِدَيْنِ مِنَ الكَبَائِرِ الَّتِي يُعَجَّلُ لِصَاحِبِهَا العُقُوبَةُ فِي الدُّنْيَا قَبْلَ الآخِرَةِ».",
