            "urduTranslation": "حافظ ابن عبد البر فرماتے ہیں: خلیفہ راشد عمر بن عبد العزیز رحمہ اللہ نے فرمایا تھا: 'مجھے اس بات سے کوئی خوشی نہ ہوتی اگر صحابۂ کرام آپس میں فروعی مسائل میں اختلاف نہ فرماتے؛ کیونکہ اگر وہ اختلاف نہ کرتے تو امت کے لیے کسی مسئلے میں کوئی وسعت اور رخصت نہ رہتی!' اور امام قتادہ فرماتے ہیں: 'جس نے ائمہ کے باہمی اختلاف اور اس کے دلائل کو نہیں جانا اس کی ناک نے فقہ کی خوشبو تک نہیں سونگھی!' کیونکہ فقہاء کے اقوال اور ان کے دلائل کو جاننا انسان کے اندر وسعتِ ظرف پیدا کرتا ہے، اسے تنگ نظر تعصب سے بچاتا ہے، اور وہ اجتہادی مسائل میں ائمہ کے لیے عذر تلاش کرتا ہے اور ہر ایک کی قدر کرتا ہے'۔",
