            "arabicText": "قَالَ عَلِيُّ الجَارِمُ وَمُصْطَفَى أَمِينٌ: «التَّشْبِيهُ: بَيَانُ أَنَّ شَيْئاً أَوْ أَشْيَاءَ شَارَكَتْ غَيْرَهَا فِي صِفَةٍ أَوْ أَكْثَرَ، بِأَدَاةٍ هِيَ الكَافُ أَوْ نَحْوُهَا. وَأَرْكَانُ التَّشْبِيهِ أَرْبَعَةٌ: المُشَبَّهُ، وَالمُشَبَّهُ بِهِ (وَيُسَمَّيَانِ طَرَفَيِ التَّشْبِيهِ)، وَأَدَاةُ التَّشْبِيهِ، وَوَجْهُ الشَّبَهِ. مِثْلُ: «العِلْمُ كَالنُّورِ فِي الهِدَايَةِ». فَإِذَا حُذِفَتِ الأَدَاةُ وَوَجْهُ الشَّبَهِ سُمِّيَ: «تَشْبِيهاً بَلِيغاً»، مِثْلُ: «العِلْمُ نُورٌ»، وَهُوَ أَعْلَى مَرَاتِبِ التَّشْبِيهِ فِي البَلَاغَةِ؛ لِأَنَّهُ يَدَّعِي أَنَّ المُشَبَّهَ عَيْنُ المُشَبَّهِ بِهِ».",
