            "id": "maqamat_hariri_seg_1_1",
            "arabicText": "قَالَ أَبُو مُحَمَّدٍ القَاسِمُ بْنُ عَلِيٍّ الحَرِيرِيُّ: «رَوَى الحَارِثُ بْنُ هَمَّامٍ قَالَ: وَفَدْتُ صَنْعَاءَ اليَمَنِ وَأَنَا خَاوِي الوِفَاضِ، فَدَخَلْتُ جَامِعَهَا فَإِذَا بِشَيْخٍ ذِي طِمْرَيْنِ رَثَّيْنِ يَقِفُ خَطِيباً يَنْثُرُ الدُّرَرَ، فَقَالَ: «يَا أَهْلَ صَنْعَاءَ، يَا مَأْوَى الغُرَبَاءِ، اعْلَمُوا أَنَّ الدُّنْيَا دَارُ مَمَرٍّ لَا دَارُ مَقَرٍّ، شَهْدُهَا مَمْزُوجٌ بِالسَّمِّ، وَصَفْوُهَا مَشُوبٌ بِالهَمِّ! كَمْ غَرَّتْ مِنْ مَغْرُورٍ، وَكَمْ كَدَّرَتْ مِنْ سُرُورٍ! أَيْنَ المُلُوكُ الأَقْدَمُونَ، وَأَيْنَ الجَبَابِرَةُ الأَوَّلُونَ؟! صَارُوا رَمِيماً فِي التُّرَابِ، وَخَلَوْا بِمَا قَدَّمُوا لِلْحِسَابِ!». فَانْهَالَتْ عَلَيْهِ الدَّرَاهِمُ كَالمَطَرِ، ثُمَّ انْكَشَفَ لِي أَنَّهُ الشَّيْخُ أَبُو زَيْدٍ السَّرُوجِيُّ سَيِّدُ الحِيلَةِ وَالأَدَبِ!».",
            "urduTranslation": "ابو محمد قاسم بن علی الحریری بصری رحمہ اللہ فرماتے ہیں: 'راوی حارث بن ہمام بیان کرتا ہے کہ میں یمن کے شہر صنعاء میں اس حال میں پہنچا کہ میری جیب خالی تھی، میں جامع مسجد میں داخل ہوا تو کیا دیکھتا ہوں کہ دو پرانے کپڑوں میں ملبوس ایک بزرگ خطیب کی طرح کھڑا موتی برسا رہا ہے، وہ پکار رہا تھا: 'اے صنعاء کے لوگو! اے مسافروں کی پناہ گاہو! خوب جان لو کہ یہ دنیا گزر گاہ ہے، مستقل رہنے کا ٹھکانہ نہیں؛ اس کا شہد زہر میں ملا ہوا ہے، اور اس کا سکون فکر و غم سے آلودہ ہے! اس نے کتنے ہی دھوکے بازوں کو فریب دیا، اور کتنی ہی خوشیوں کو خاک میں ملا دیا! کہاں گئے وہ پرانے بادشاہ اور کہاں گئے وہ پہلے جابر حکمران؟! سب مٹی میں ہڈیاں بن کر گل سڑ گئے اور اپنے اعمال کے حساب کے لیے تنہا رہ گئے!' پس سامعین کے دل پگھل گئے اور اس پر درہموں کی بارش ہونے لگی، پھر بعد میں مجھ پر کھلا کہ یہ تو وہی چالاک بزرگ ابو زید سروجی ہے جو ادب اور حیلہ سازی کا بے تاج بادشاہ تھا!'",
