            "id": "maqamat_hariri_seg_2_1",
            "arabicText": "«أَبْدَعَ الحَرِيرِيُّ فِي مَقَامَاتِهِ فُنُوناً لُغَوِيَّةً لَا يَقْدِرُ عَلَيْهَا إِلَّا مَلِكُ البَلَاغَةِ؛ مِنْهَا خُطَبٌ كَامِلَةٌ خَالِيَةٌ مِنَ النِّقَاطِ (العَاطِلَةُ)، كَقَوْلِهِ: «الحَمْدُ لِلَّهِ المَلِكِ المَحْمُودِ، المَالِكِ الوَدُودِ، مُصَوِّرِ كُلِّ مَوْلُودٍ، وَمَآلِ كُلِّ مَطْرُودٍ!». وَمِنْهَا الكَلَامُ المَقْلُوبُ الَّذِي يُقْرَأُ طَرْداً وَعَكْساً بِلَا تَفَاوُتٍ، كَقَوْلِهِ: «سِرْ فَلَا كَبَا بِكَ الفَرَسُ»، وَقَوْلِهِ: «عَقْرَبٌ يَرْقَى بِقُرْبِ قَعْرٍ». فَكَانَتْ مَقَامَاتُهُ مِعْيَارَ الذَّوْقِ الأَدَبِيِّ فِي كُلِّ عَصْرٍ».",
            "urduTranslation": "حریری رحمہ اللہ فرماتے ہیں: 'انہوں نے اپنے مقامات میں ایسے محیر العقول لغوی فنون دکھائے جن پر بلاغت کے سلطان کے سوا کسی کو دسترس نہیں ہوتی؛ جن میں ایسے مکمل خطبے ہیں جن میں ایک بھی نقطے والا حرف نہیں ہے (خطبۂ عاطلہ)، جیسے ان کا یہ کلام: 'سب تعریف اللہ کے لیے ہے جو لائقِ حمد بادشاہ ہے، محبت کرنے والا مالک ہے، ہر پیدا ہونے والے کا صورت گر ہے، اور ہر دھتکارے ہوئے کی پناہ گاہ ہے!' (اس پورے جملے میں ایک نقطہ بھی نہیں ہے)۔ اور جن میں ایسا الٹ پلٹ کلام (مقلوب مستوی) ہے جسے شروع سے آخر تک پڑھیں یا آخر سے شروع کی طرف الٹا پڑھیں تو بالکل وہی الفاظ اور وہی معنی برقرار رہتا ہے، جیسے: 'سِرْ فَلَا كَبَا بِكَ الفَرَسُ' (سفر کرو تاکہ گھوڑا تمہیں لے کر نہ گرے)۔ چنانچہ مقاماتِ حریری ہر دور میں عربی زبان کے ادبی ذوق کا سب سے بلند پیمانہ بنی رہی'۔",
