            "arabicText": "قَالَ السَّيِّدُ أَحْمَدُ الهَاشِمِيُّ: «الفَصَاحَةُ فِي اللُّغَةِ: البَيَانُ وَالظُّهُورُ، وَفِي الِاصْطِلَاحِ: عِبَارَةٌ عَنِ الأَلْفَاظِ البَيِّنَةِ الخَفِيفَةِ عَلَى اللِّسَانِ، الخَالِيَةِ مِنْ عُيُوبٍ ثَلَاثَةٍ: تَنَافُرِ الحُرُوفِ (كَقَوْلِهِمْ: هُعْخُعٌ لِلنَّبْتِ)، وَغَرَابَةِ الِاسْتِعْمَالِ، وَمُخَالَفَةِ القِيَاسِ الصَّرْفِيِّ. أَمَّا البَلَاغَةُ: فَهِيَ مُطَابَقَةُ الكَلَامِ الفَصِيحِ لِمُقْتَضَى حَالِ السَّامِعِينَ مَعَ فَصَاحَتِهِ؛ فَكُلُّ كَلَامٍ بَلِيغٍ فَصِيحٌ، وَلَيْسَ كُلُّ فَصِيحٍ بَلِيغاً؛ إِذْ قَدْ يَكُونُ الكَلَامُ فِي غَايَةِ الفَصَاحَةِ لَكِنَّهُ لَا يُنَاسِبُ المَقَامَ كَأَنْ يُلْقَى خِطَابُ التَّهْنِئَةِ فِي مَجْلِسِ العَزَاءِ!».",
