            "id": "jawahir_hashimi_seg_2_1",
            "arabicText": "«عِلْمُ البَدِيعِ: هُوَ عِلْمٌ يُعْرَفُ بِهِ وُجُوهُ تَحْسِينِ الكَلَامِ بَعْدَ رِعَايَةِ مُطَابَقَتِهِ لِمُقْتَضَى الحَالِ. وَالمُحَسِّنَاتُ نَوْعَانِ: 1. مُحَسِّنَاتٌ مَعْنَوِيَّةٌ: وَأَهَمُّهَا «الطِّبَاقُ» وَهُوَ الجَمْعُ بَيْنَ الشَّيْءِ وَضِدِّهِ، كَقَوْلِهِ: {وَتَحْسَبُهُمْ أَيْقَاظاً وَهُمْ رُقُودٌ}، وَ«المُقَابَلَةُ» وَهِيَ أَنْ يُؤْتَى بِمَعْنَيَيْنِ أَوْ أَكْثَرَ ثُمَّ يُؤْتَى بِمَا يُقَابِلُ ذَلِكَ عَلَى التَّرْتِيبِ، كَقَوْلِهِ: {فَلْيَضْحَكُوا قَلِيلاً وَلْيَبْكُوا كَثِيراً}. 2. مُحَسِّنَاتٌ لَفْظِيَّةٌ: كَـ «الجِنَاسِ التَّامِّ» الَّذِي يَتَّفِقُ فِيهِ اللَّفْظَانِ فِي أَرْبَعَةِ أُمُورٍ: الحُرُوفِ، وَعَدَدِهَا، وَهَيْئَتِهَا، وَتَرْتِيبِهَا مَعَ اخْتِلَافِ المَعْنَى، كَقَوْلِهِ: {وَيَوْمَ تَقُومُ السَّاعَةُ يُقْسِمُ الْمُجْرِمُونَ مَا لَبِثُوا غَيْرَ سَاعَةٍ}؛ فَالسَّاعَةُ الأُولَى: يَوْمُ القِيَامَةِ، وَالثَّانِيَةُ: الوَقْتُ مِنَ الزَّمَانِ».",
