            "urduTranslation": "ابن ہشام فرماتے ہیں: 'عربی زبان میں مرفوعات (پیش پڑھے جانے والے اسماء) کل سات ہیں: فاعل، نائب الفاعل (یعنی وہ مفعول جس کے فاعل کو خوف، تعظیم یا اختصار کی وجہ سے حذف کر دیا گیا ہو اور مفعول کو فاعل کا مقام دے دیا گیا ہو، جیسے: {انسان کمزور پیدا کیا گیا ہے})، مبتدا، خبر، کان اور اس کی بہنوں کا اسم، اِنَّ اور اس کی بہنوں کی خبر، اور مرفوع کا تابع (جو نعت، عطف، تاکید اور بدل پر مشتمل ہے)۔ اور مفعول اس وقت تک کبھی مرفوع نہیں ہوتا جب تک کہ فاعل کو حذف کر کے فعل کی بنا کو ماضی میں پہلے حرف کو پیش اور آخری سے پہلے کو زیر دے کر مجہول نہ بنا دیا جائے'۔",
