            "urduTranslation": "علامہ ندوی فرماتے ہیں: 'امیر المؤمنین حضرت عمر فاروق رضی اللہ عنہ مسجد میں تشریف لائے تو دیکھا کہ کچھ ہٹے کٹے لوگ ہاتھ پر ہاتھ دھرے بیٹھے ہیں، کوئی کام کاج نہیں کرتے اور لوگوں کے آگے ہاتھ پھیلاتے ہیں، حضرت عمر نے پوچھا: 'تم کون لوگ ہو؟' انہوں نے کہا: 'ہم اللہ پر توکل کرنے والے درویش ہیں!' تو فاروقِ اعظم نے اپنا کوڑا اٹھایا اور غضبناک ہو کر فرمایا: 'جھوٹ بکتے ہو! تم متوکل نہیں بلکہ دوسروں کے ٹکڑوں پر پلنے والے مفت خورے ہو! خبردار! تم میں سے کوئی شخص حلال روزی کی تلاش چھوڑ کر مسجد کے کونے میں نہ بیٹھے اور یہ دعا نہ کرے کہ اے اللہ مجھے رزق دے، حالانکہ وہ خوب جانتا ہے کہ آسمان سے کبھی سونے چاندی کی بارش نہیں برستی، اور اللہ لوگوں کو ایک دوسرے کے ذریعے محنت کے بدلے رزق عطا فرماتا ہے!' اور رسول اللہ ﷺ کا ارشاد ہے: 'کسی انسان نے اس کھانے سے بہتر کھانا کبھی نہیں کھایا جو اس نے اپنے ہاتھوں کی محنت سے کمایا ہو، اور اللہ کے برگزیدہ پیغمبر حضرت داؤد علیہ السلام بھی اپنے ہاتھوں کی محنت (زرہ سازی) سے کما کر کھاتے تھے'۔",
