            "arabicText": "«قَالَ ابْنُ خُزَيْمَةَ: نَحْنُ نُقِرُّ بِلِسَانِنَا، وَنَعْتَقِدُ بِقُلُوبِنَا، أَنَّ لِرَبِّنَا عَزَّ وَجَلَّ يَدَيْنِ مَوْصُوفَتَيْنِ بِالجَلَالِ وَالإِكْرَامِ، كَمَا نَطَقَ كِتَابُهُ فِي قَوْلِهِ لِإِبْلِيسَ: {مَا مَنَعَكَ أَنْ تَسْجُدَ لِمَا خَلَقْتُ بِيَدَيَّ}، وَقَالَ ﷺ: «يَمِينُ اللَّهِ مَلْأَى لَا يَغِيضُهَا نَفَقَةٌ، سَحَّاءُ اللَّيْلَ وَالنَّهَارَ». وَلَا نُشَبِّهُ يَدَيْ خَالِقِنَا بِأَيْدِي المَخْلُوقِينَ؛ فَمَنْ شَبَّهَ اللَّهَ بِخَلْقِهِ فَهُوَ مُشَبِّهٌ ضَالٌّ، وَمَنْ أَنْكَرَ مَا وَصَفَ اللَّهُ بِهِ نَفْسَهُ فَهُوَ جَهْمِيٌّ مُعَطِّلٌ، وَأَهْلُ السُّنَّةِ وَسَطٌ بَيْنَ التَّشْبِيهِ وَالتَّعْطِيلِ».",
            "urduTranslation": "امام ابن خزیمہ فرماتے ہیں: 'ہم اپنی زبان سے اقرار کرتے ہیں اور اپنے دلوں سے یہ پختہ عقیدہ رکھتے ہیں کہ ہمارے رب عزوجل کے دو دستِ مبارک ہیں جو جلال اور اکرام سے متصف ہیں جیسا کہ اس کی کتاب نے ابلیس سے خطاب کرتے ہوئے فرمایا: {تجھے اس ہستی (آدم) کو سجدہ کرنے سے کس چیز نے روکا جسے میں نے اپنے دونوں ہاتھوں سے بنایا}، اور رسول اللہ ﷺ نے فرمایا: 'اللہ کا دایاں ہاتھ بھرا ہوا ہے جسے شب و روز کی بارش کی طرح سخاوت بھی کم نہیں کر سکتی'۔ اور ہم اپنے خالق کے دستِ مبارک کو مخلوق کے ہاتھوں کے مشابہ نہیں ٹھہراتے؛ پس جس نے اللہ کو اس کی مخلوق سے تشبیہ دی وہ گمراہ مشبہ ہے، اور جس نے ان صفات کا انکار کیا وہ گمراہ جہمی معطل ہے، اور اہل سنت والجماعت تشبیہ اور انکار کے درمیان عین اعتدال کی شاہراہ پر ہیں'۔",
