            "urduTranslation": "شیخ الاسلام فرماتے ہیں: 'اور اہل سنت والجماعت صحابہ کرام کے باہمی مشاجرات اور اختلافات پر اپنی زبانیں بند رکھتے ہیں؛ اور وہ جانتے ہیں کہ صحابہ کے بارے میں جو برائیاں اور روایات نقل کی گئی ہیں ان میں سے کثیر جھوٹی اور گھڑی ہوئی ہیں، اور جو روایات صحیح سند سے ہیں ان میں وہ معذور اور صاحبِ اجتہاد تھے: یا تو وہ مجتہد تھے جنہوں نے درست فیصلہ کیا تو ان کے لیے دہرا اجر ہے، اور یا وہ مجتہد تھے جن سے خطا ہوئی تو ان کے لیے اجتہاد کا ایک اجر ہے اور ان کی خطا معاف ہے؛ اور ان کے پاس اسلام کی اولین قربانیاں، جہاد اور ایسی فضیلتیں ہیں جو ان کی تمام لغزشوں کو مٹا دینے کے لیے کافی ہیں۔ اور رسول اللہ ﷺ نے فرمایا: 'میرے صحابہ کو گالی مت دو! قسم ہے اس ذات کی جس کے ہاتھ میں میری جان ہے! اگر تم میں سے کوئی احد پہاڑ کے برابر بھی سونا خیرات کر دے تو وہ ان کے ایک سیر یا آدھے سیر جو کے صدقے کے برابر بھی نہیں پہنچ سکتا!'",
